// CDP smoke + functional test for index.html (no deps; Node >= 22 has WebSocket)
const { execFileSync, spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const FILE = 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-oy82_7vg/run/index.html';
const PORT = 9333;
const sleep = ms => new Promise(r => setTimeout(r, ms));

function cdpCall(ws, id, method, params = {}) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('CDP timeout: ' + method)), 15000);
    const onMsg = ev => {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        clearTimeout(timer);
        ws.removeEventListener('message', onMsg);
        if (msg.error) reject(new Error(method + ': ' + JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', onMsg);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

(async () => {
  const userDir = '/tmp/chrome-smoke-' + Date.now();
  const chrome = spawn('/usr/bin/google-chrome', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDir}`, 'about:blank',
  ], { stdio: ['ignore', 'pipe', 'pipe'] });

  // wait for devtools endpoint
  let target;
  for (let i = 0; i < 50; i++) {
    try {
      const list = JSON.parse(execFileSync('curl', ['-s', `http://127.0.0.1:${PORT}/json`]).toString());
      target = list.find(t => t.type === 'page');
      if (target) break;
    } catch (_) {}
    await sleep(250);
  }
  if (!target) throw new Error('chrome devtools not up');

  await cdpCallByHttp(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(FILE)}`).catch(async () => {
    // older: use existing target
  });

  // (re)open tab with our file
  let list = JSON.parse(execFileSync('curl', ['-s', `http://127.0.0.1:${PORT}/json`]).toString());
  let our = list.find(t => t.type === 'page' && (t.url || '').includes('index.html'));
  if (!our) {
    const created = await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(FILE)}`, { method: 'PUT' }).then(r => r.json()).catch(() => null);
    if (created) our = created;
    else {
      // navigate the blank tab
      our = list.find(t => t.type === 'page');
    }
  }

  const ws = new WebSocket(our.webSocketDebuggerUrl);
  let seq = 0;
  const send = (method, params = {}) => cdpCall(ws, ++seq, method, params);
  const events = [];
  ws.onmessage = ev => {
    const m = JSON.parse(ev.data);
    if (m.method) events.push(m);
  };
  await new Promise(r => (ws.onopen = r));

  const results = [];
  const check = (name, cond, extra='') => {
    results.push({ name, ok: !!cond, extra });
    console.log((cond ? 'PASS' : 'FAIL'), name, extra);
  };

  if (!our.url.includes('index.html')) await send('Page.navigate', { url: FILE });
  await send('Runtime.enable');
  await send('Page.enable');
  const loaded = new Promise(resolve => {
    const onMsg = ev => {
      const m = JSON.parse(ev.data);
      if (m.method === 'Page.loadEventFired') { ws.removeEventListener('message', onMsg); resolve(); }
    };
    ws.addEventListener('message', onMsg);
    setTimeout(resolve, 6000);
  });
  // page may have already loaded; poll instead
  for (let i = 0; i < 40 && (await send('Runtime.evaluate', { expression: 'document.readyState' }).catch(() => ({ result: { value: 'loading' } }))).result.value !== 'complete'; i++) await sleep(100);
  await loaded;
  await sleep(200);

  const ev = expr => send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });

  // 1) structural
  const st = await ev(`JSON.stringify({
    steps: document.querySelectorAll('#steps .step').length,
    lists: document.querySelectorAll('#steps .disc-list').length,
    items: document.querySelectorAll('#steps .disc-item').length,
    tabs: document.querySelectorAll('#tabs button').length,
    overlayHidden: document.getElementById('overlay').hidden,
    itemsWithType: Array.from(document.querySelectorAll('#steps .disc-item')).every(li => ['d','i','s','c'].includes(li.dataset.type))
  })`));
  const s = JSON.parse(st.result.value);
  check('structure: 8 steps / 24 lists / 96 items / 8 tabs', s.steps === 8 && s.lists === 24 && s.items === 96 && s.tabs === 8, JSON.stringify(s));
  check('all items have valid data-type', s.itemsWithType);

  // 2) data spot checks (verbatim incl. quirks)
  const spot = await ev(`JSON.stringify({
    hasLatinC: Array.from(document.querySelectorAll('.disc-item .txt')).some(e => e.textContent === 'Экспресcивный'),
    hasSpace: Array.from(document.querySelectorAll('.disc-item .txt')).some(e => e.textContent === 'Готовый к сотрудничеству'),
    list1: Array.from(document.querySelectorAll('#steps .step')[0].querySelectorAll('.disc-item')).map(li => li.dataset.type)
  })`));
  const sp = JSON.parse(spot.result.value);
  check('verbatim texts incl. Latin-c quirk + spaces', sp.hasLatinC && sp.hasSpace);
  check('step1 types order == i,c,d,s', sp.list1.join('') === 'icds', sp.list1.join(''));

  // 3) open dialog
  await ev(`document.getElementById('btnOpen').click(); true`);
  await sleep(80);
  check('overlay opens on CTA click', (await ev(`document.getElementById('overlay').hidden`)).result.value === false);
  check('step 1 active, btnPrev disabled, finish hidden',
    (await ev(`JSON.stringify({
      a: document.querySelectorAll('#tabs button')[0].classList.contains('is-active'),
      b: document.getElementById('btnPrev').disabled,
      c: document.getElementById('btnFinish').hidden
    })`)).result.value && JSON.parse((await ev(`JSON.stringify({
      a: document.querySelectorAll('#tabs button')[0].classList.contains('is-active'),
      b: document.getElementById('btnPrev').disabled,
      c: document.getElementById('btnFinish').hidden
    })`)).result.value).a);

  // 4) drag & drop simulation (pointer events via CDP mouse):
  //    move FIRST item (idx0) to LAST position in list 1
  const rect = await ev(`(function(){
    const li = document.querySelectorAll('#steps .step')[0].querySelectorAll('.disc-item');
    const r = li[0].getBoundingClientRect();
    const r3 = li[3].getBoundingClientRect();
    return JSON.stringify({x: r.left + r.width/2, y0: r.top + r.height/2, y3: r3.top + r3.height/2});
  })()`);
  const R = JSON.parse(rect.result.value);
  const move = (x, y) => send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y, button: 'none', buttons: 1 });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: R.x, y: R.y0, button: 'left', clickCount: 1 });
  for (let y = R.y0; y <= R.y3 + 30; y += 12) { await move(R.x, y); await sleep(12); }
  await sleep(60);
  const orderAfterDrag = (await ev(`Array.from(document.querySelectorAll('#steps .step')[0].querySelectorAll('.disc-item')).map(li => li.textContent.trim())`)).result.value;
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: R.x, y: R.y3 + 30, button: 'left', clickCount: 1 });
  await sleep(80);
  const orderFinal = (await ev(`Array.from(document.querySelectorAll('#steps .step')[0].querySelectorAll('.disc-item')).map(li => li.textContent.trim())`)).result.value;
  const first0 = 'Экспресcивный';
  check('drag reorders item first->last', orderFinal.length === 4 && orderFinal[0] !== first0 && orderFinal[3] === first0, orderFinal.join(' | '));
  check('drag visual state cleaned up', (await ev(`document.querySelectorAll('.is-drag').length === 0 && document.querySelectorAll('.disc-item').length === 96`)).result.value);

  // 5) step navigation to end
  for (let i = 0; i < 7; i++) await ev(`document.getElementById('btnNext').click(); true`);
  await sleep(60);
  const nav = JSON.parse((await ev(`JSON.stringify({
    step8: Array.from(document.querySelectorAll('#steps .step')).every((p,i) => p.hidden === (i !== 7)),
    finishVisible: !document.getElementById('btnFinish').hidden,
    barW: document.getElementById('barFill').style.width,
    nextHidden: document.getElementById('btnNext').hidden
  })`)).result.value));
  check('navigated to step 8 (finish visible, 100% bar)', nav.step8 && nav.finishVisible && nav.nextHidden, nav.barW);

  // 6) deterministic scoring: force all d-qualities to position 0, i→1, s→2, c→3
  await ev(`(function(){
    const rank = { d:0, i:1, s:2, c:3 };
    document.querySelectorAll('#steps .disc-list').forEach(ul => {
      Array.from(ul.children).sort((a,b) => rank[a.dataset.type] - rank[b.dataset.type]).forEach(li => ul.appendChild(li));
    });
    return true;
  })()`);
  await ev(`document.getElementById('btnFinish').click(); true`);
  await sleep(120);
  const res = JSON.parse((await ev(`JSON.stringify({
    resultVisible: !document.getElementById('resultPane').hidden,
    quizHidden: document.getElementById('quizPane').hidden,
    line: document.getElementById('scoreLine').textContent.trim(),
    cards: Array.from(document.querySelectorAll('.rcard .val')).map(v => v.textContent)
  })`)).result.value));
  check('result pane shows after finish', res.resultVisible && res.quizHidden);
  check('scores computed d=+6,i=0,s=0,c=-6', res.line === 'D: 6 I: 0 S: 0 C: -6' || res.line.replace(/ /g,'').includes('D:6I:0S:0C:-6'), JSON.stringify(res));
  check('result cards match', JSON.stringify(res.cards) === JSON.stringify(['+6','0','0','-6']), res.cards.join(','));

  // 7) restart resets to original order
  await ev(`document.getElementById('btnRestart').click(); true`);
  await sleep(120);
  const rst = JSON.parse((await ev(`JSON.stringify({
    quizVisible: !document.getElementById('quizPane').hidden,
    resultHidden: document.getElementById('resultPane').hidden,
    firstItem: document.querySelectorAll('#steps .disc-item')[0].textContent.trim(),
    items: document.querySelectorAll('.disc-item').length
  })`)).result.value));
  check('restart restores quiz + original order', rst.quizVisible && rst.resultHidden && rst.firstItem === 'Экспресcивный' && rst.items === 96);

  // 8) JS errors?
  const errs = events.filter(e => e.method === 'Runtime.exceptionThrown');
  check('no uncaught JS errors', errs.length === 0, errs[0] ? JSON.stringify(errs[0].params.exceptionDetails).slice(0, 300) : '');

  const failed = results.filter(r => !r.ok).length;
  console.log('\n==== %d/%d checks passed ====', results.length - failed, results.length);
  ws.close();
  chrome.kill('SIGTERM');
  process.exit(failed ? 1 : 0);
})().catch(e => { console.error('TEST RUNNER ERROR:', e.message); try { require('child_process').execSync('pkill -f remote-debugging-port=9333'); } catch(_){} process.exit(2); });

