let seq = 0;
(async () => {
  const PORT = 9340;
  const chrome = spawn('/usr/bin/google-chrome', ['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage',`--remote-debugging-port=${PORT}`,`--user-data-dir=/tmp/ct6-`+Date.now(),'about:blank'], { stdio: 'ignore' });
  let target = null;
  for (let i = 0; i < 60; i++) {
    try { const l = JSON.parse(execFileSync('curl', ['-s', `http://127.0.0.1:${PORT}/json`]).toString()); target = l.find(t => t.type === 'page'); if (target) break; } catch(_){}
    await sleep(250);
  }
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
  const send = (method, params={}) => new Promise((res, rej) => {
    const id = ++seq;
    const onM = ev2 => { const m = JSON.parse(ev2.data); if (m.id === id){ ws.removeEventListener('message', onM); m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result); } };
    ws.addEventListener('message', onM);
    ws.send(JSON.stringify({id, method, params}));
  });
  const ev = async e => {
    const r = await send('Runtime.evaluate', { expression: e, returnByValue: true });
    if (r.exceptionDetails) throw new Error('page exception: ' + (r.exceptionDetails.exception && r.exceptionDetails.exception.description || r.exceptionDetails.text));
    return r.result.value;
  };
  await send('Runtime.enable'); await send('Page.enable');
  await send('Page.navigate', { url: 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-oy82_7vg/run/index.html' });
  for (let i=0;i<60;i++){ if((await ev('document.readyState'))==='complete') break; await sleep(100); }
  await sleep(200);
  await ev(`document.getElementById('btnOpen').click()`);
  await sleep(150);

  // instrument THE app's first ul
  await ev(`(() => {
    window.__ev = [];
    const ul = document.querySelector('#steps .step .disc-list');
    ['pointerdown','pointermove','pointerup','pointercancel','mousedown','mousemove','mouseup'].forEach(function(t){
      ul.addEventListener(t, function(e){ window.__ev.push(t + (e.clientY != null ? ' y=' + Math.round(e.clientY) : '') + ' pid=' + e.pointerId + (e.buttons != null ? ' btn=' + e.buttons : '')); });
    });
    return true;
  })()`);
  const v = await ev(`(() => { const li = document.querySelector('#steps .step .disc-item');
    const r = li.getBoundingClientRect();
    const hit = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2);
    return { x: Math.round(r.left + r.width/2), y: r.top + r.height/2,
             hitTag: hit ? hit.tagName : 'NULL', hitCls: hit ? String(hit.className).slice(0,40) : '' }; })()`);
  console.log('li0 point/hit:', JSON.stringify(v));
  // CDP drag down
  const r3y = await ev(`(() => { const li = document.querySelectorAll('#steps .step .disc-list')[0].querySelectorAll('.disc-item')[3]; return li.getBoundingClientRect().bottom + 30; })()`);
  await send('Input.dispatchMouseEvent', { type:'mousePressed', x:v.x, y:v.y, button:'left', clickCount:1, buttons:1 });
  for (let i=1;i<=25;i++){ await send('Input.dispatchMouseEvent', { type:'mouseMoved', x:v.x, y: v.y + (r3y-v.y)*i/25, button:'none', buttons:1 }); await sleep(12); }
  await send('Input.dispatchMouseEvent', { type:'mouseReleased', x:v.x, y:r3y, button:'left', clickCount:1, buttons:0 });
  await sleep(200);
  console.log('events on app ul:', JSON.stringify(await ev(`window.__ev`)));
  console.log('order after CDP drag:', await ev(`Array.from(document.querySelectorAll('#steps .step .disc-list')[0].querySelectorAll('.disc-item')).map(li=>li.textContent.trim()).join('|')`));

  // SYNTHETIC pointer events on the same ul (control)
  await ev(`(() => {
    const ul = document.querySelectorAll('#steps .step .disc-list')[0];
    const li = ul.querySelectorAll('.disc-item')[0];
    const r0 = li.getBoundingClientRect(), r3 = ul.querySelectorAll('.disc-item')[3].getBoundingClientRect();
    const x = r0.left + r0.width/2, y0 = r0.top + r0.height/2, y1 = r3.bottom + 10;
    const mk = (t, y) => new PointerEvent(t, {bubbles:true, cancelable:true, pointerId:9, pointerType:'mouse', isPrimary:true, button: t==='pointerdown'?0:-1, buttons: t==='pointerup'?0:1, clientX:x, clientY:y, view:window});
    ul.dispatchEvent(mk('pointerdown', y0));
    for (let i=1;i<=20;i++) ul.dispatchEvent(mk('pointermove', y0 + (y1-y0)*i/20));
    ul.dispatchEvent(mk('pointerup', y1));
    return true;
  })()`);
  await sleep(150);
  console.log('order after synthetic:', await ev(`Array.from(document.querySelectorAll('#steps .step .disc-list')[0].querySelectorAll('.disc-item')).map(li=>li.textContent.trim()).join('|')`));
  ws.close(); chrome.kill('SIGTERM'); setTimeout(()=>process.exit(0),150);
})().catch(e => { console.error('ERR', e.message); try{execFileSync('pkill',['-f','remote-debugging-port=9340'])}catch(_){} process.exit(2); });
