// Full functional test: index.html via headless Chrome + CDP (Node >= 22)
const { execFileSync, spawn } = require('child_process');
const FILE = 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-oy82_7vg/run/index.html';
const PORT = 9350;
const sleep = ms => new Promise(r => setTimeout(r, ms));
let seq = 0, failed = 0;

(async () => {
  const chrome = spawn('/usr/bin/google-chrome', [
    '--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage',
    '--window-size=1100,900', `--remote-debugging-port=${PORT}`,
    `--user-data-dir=/tmp/st-` + Date.now(), 'about:blank'
  ], { stdio: 'ignore' });

  let target = null;
  for (let i = 0; i < 60; i++) {
    try {
      const l = JSON.parse(execFileSync('curl', ['-s', `http://127.0.0.1:${PORT}/json`]).toString());
      target = l.find(t => t.type === 'page');
      if (target) break;
    } catch (_) {}
    await sleep(250);
  }
  if (!target) throw new Error('chrome devtools not up');

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
  const send = (method, params = {}) => new Promise((res, rej) => {
    const id = ++seq;
    const onM = ev2 => {
      const m = JSON.parse(ev2.data);
      if (m.id === id) {
        ws.removeEventListener('message', onM);
        m.error ? rej(new Error(method + ': ' + JSON.stringify(m.error))) : res(m.result);
      }
    };
    ws.addEventListener('message', onM);
    ws.send(JSON.stringify({ id, method, params }));
  });
  const ev = async e => {
    const r = await send('Runtime.evaluate', { expression: e, returnByValue: true });
    if (r.exceptionDetails) throw new Error('page exception: ' + (r.exceptionDetails.exception && r.exceptionDetails.exception.description || r.exceptionDetails.text));
    return r.result.value;
  };
  const exceptions = [];
  ws.addEventListener('message', m2 => {
    const m = JSON.parse(m2.data);
    if (m.method === 'Runtime.exceptionThrown') exceptions.push(m.params.exceptionDetails);
  });

  const check = (name, cond, extra = '') => {
    if (!cond) failed++;
    console.log((cond ? 'PASS ' : 'FAIL ') + name + (extra ? '  [' + extra + ']' : ''));
  };

  await send('Runtime.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: FILE });
  for (let i = 0; i < 60; i++) { if ((await ev('document.readyState')) === 'complete') break; await sleep(100); }
  await sleep(250);

  // ---------- 1. структура ----------
  let v = await ev(`(() => ({
    steps: document.querySelectorAll('#steps .step').length,
    lists: document.querySelectorAll('#steps .disc-list').length,
    items: document.querySelectorAll('#steps .disc-item').length,
    tabs: document.querySelectorAll('#tabs button').length,
    typesOk: Array.from(document.querySelectorAll('#steps .disc-item')).every(li => ['d','i','s','c'].includes(li.dataset.type)),
    overlayHidden: document.getElementById('overlay').hidden
  }))()`);
  check('структура: 8 шагов / 24 списка / 96 пунктов / 8 табов',
    v.steps === 8 && v.lists === 24 && v.items === 96 && v.tabs === 8 && v.typesOk && v.overlayHidden, JSON.stringify(v));

  // ---------- 2. данные дословно ----------
  v = await ev(`(() => {
    const t = Array.from(document.querySelectorAll('#steps .disc-item .txt')).map(e => e.textContent);
    return {
      quirkLatinC: t.includes('Экспресcивный'),
      spaceText: t.includes('Готовый к сотрудничеству'),
      list1types: Array.from(document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item')).map(li => li.dataset.type).join('')
    };
  })()`);
  check('данные дословно («Экспресcивный» с латинской c, «Готовый к сотрудничеству»); шаг 1 список 1: i,c,d,s',
    v.quirkLatinC && v.spaceText && v.list1types === 'icds', JSON.stringify(v));

  // ---------- 3. открытие ----------
  await ev(`document.getElementById('btnOpen').click()`);
  await sleep(80);
  v = await ev(`(() => ({
    open: !document.getElementById('overlay').hidden,
    step1Active: document.querySelectorAll('#tabs button')[0].classList.contains('is-active'),
    step1Only: Array.from(document.querySelectorAll('#steps .step')).every((p, i) => p.hidden === (i !== 0)),
    prevDisabled: document.getElementById('btnPrev').disabled,
    finishHidden: document.getElementById('btnFinish').hidden,
    bar: document.getElementById('barFill').style.width
  }))()`);
  check('открытие: оверлей виден, активен только шаг 1, «Назад» disabled, «Завершить» скрыт, бар 12.5%',
    v.open && v.step1Active && v.step1Only && v.prevDisabled && v.finishHidden && v.bar === '12.5%', JSON.stringify(v));

  // ---------- 4. drag&drop через CDP-мышь ----------
  await ev(`(() => { const li = document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item')[0];
    document.querySelector('.dlg__body').scrollTo({ top: 0 });
    li.scrollIntoView({ block: 'center' }); return true; })()`);
  await sleep(120);
  v = await ev(`(() => {
    const li = document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item');
    const r0 = li[0].getBoundingClientRect(); const r3 = li[3].getBoundingClientRect();
    const hit = document.elementFromPoint(r0.left + r0.width / 2, r0.top + r0.height / 2);
    return { x: Math.round(r0.left + r0.width / 2), y0: r0.top + r0.height / 2, yEnd: r3.top + r3.height / 2 + 20,
             hitLi: hit && (hit.classList.contains('disc-item') || hit.closest('.disc-item') !== null),
             first: li[0].textContent.trim() };
  })()`);
  check('точка старта перетаскивания попадает в .disc-item', v.hitLi, 'hit=' + v.hitLi + ' y0=' + v.y0);
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: v.x, y: v.y0 });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', x: v.x, y: v.y0, button: 'left', clickCount: 1, buttons: 1 });
  for (let i = 1; i <= 30; i++) {
    await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: v.x, y: v.y0 + (v.yEnd - v.y0) * i / 30, button: 'none', buttons: 1 });
    await sleep(10);
  }
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: v.x, y: v.yEnd, button: 'left', clickCount: 1, buttons: 0 });
  await sleep(150);
  const listOrder = () => ev(`Array.from(document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item')).map(li => li.textContent.trim()).join('|')`);
  const afterDrag = await listOrder();
  await ev(`(() => { const li = document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item');
    li[3].scrollIntoView({ block: 'center' }); return true; })()`);
  await sleep(100);
  const v2 = await ev(`(() => {
    const li = document.querySelectorAll('#steps .disc-list')[0].querySelectorAll('.disc-item');
    const r0 = li[0].getBoundingClientRect(); const r3 = li[3].getBoundingClientRect();
    return { x: Math.round(r0.left + r0.width / 2), y0: r0.top + r0.height / 2, yEnd: r3.bottom + 20, first: li[0].textContent.trim() };
