/* ============ drag & drop (Pointer Events, live reorder) ============ */
function getInsertBefore(ul, clientY){
  const items = $$('.disc-item', ul).filter(li => !li.classList.contains('is-drag'));
  let best = {dist: Infinity, el: null};
  for (const li of items){
    const r = li.getBoundingClientRect();
    if (clientY < r.top || clientY > r.bottom) continue;
    const before = clientY - r.top < r.height / 2;
    const dist = before ? (clientY - r.top) : (r.bottom - clientY);
    if (dist < best.dist) best = {dist, el: before ? li : li.nextElementSibling};
  }
  if (!best.el){
    const first = ul.firstElementChild;
    if (!first) return null;
    const r = first.getBoundingClientRect();
    return clientY < r.top ? first : null;
  }
  return best.el;
}

let drag = null; // активное перетаскивание (общее состояние)

function makeDraggable(ul){
  ul.addEventListener('pointerdown', e => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const li = e.target.closest('.disc-item');
    if (!li || li.parentElement !== ul || drag) return;
    e.preventDefault();
    const r = li.getBoundingClientRect();
    drag = {
      ul, li,
      pointerId: e.pointerId,
      startY: e.clientY,
      liTop: r.top
    };
    li.classList.add('is-drag');
  });

  ul.addEventListener('keydown', e => {
    const li = e.target.closest('.disc-item');
    if (!li) return;
    if (e.key === 'ArrowUp' && li.previousElementSibling){
      e.preventDefault();
      ul.insertBefore(li, li.previousElementSibling);
      li.focus();
    } else if (e.key === 'ArrowDown' && li.nextElementSibling){
      e.preventDefault();
      ul.insertBefore(li, li.nextElementSibling);
      li.focus();
    }
  });
}

function onDragMove(e){
  if (!drag || e.pointerId !== drag.pointerId) return;
  e.preventDefault();
  const {li, ul} = drag;
  const baseTop = li.getBoundingClientRect().top - (li._ty || 0);
  const ty = (e.clientY - drag.startY) + (drag.liTop - baseTop);
  li._ty = ty;
  li.style.transform = 'translateY(' + ty + 'px)';

  const ref = getInsertBefore(ul, e.clientY);
  if (ref !== li){
    if (ref && ref !== li.nextElementSibling) ul.insertBefore(li, ref);
    else if (!ref && li.nextElementSibling) ul.insertBefore(li, li.nextElementSibling);
    else if (!ref && li !== ul.lastElementChild) ul.appendChild(li);
  }

  // автопрокрутка диалога у краёв
  const dlgBody = $('.dlg__body');
  const br = dlgBody.getBoundingClientRect();
  const m = 70;
  if (e.clientY < br.top + m) dlgBody.scrollTop -= (br.top + m - e.clientY);
  else if (e.clientY > br.bottom - m) dlgBody.scrollTop += (e.clientY - (br.bottom - m));
}

function endDrag(e){
  if (!drag) return;
  if (e && e.type === 'pointerup' && e.pointerId !== drag.pointerId) return;
  const {li} = drag;
  li.style.transform = '';
  li._ty = 0;
  li.classList.remove('is-drag');
  drag = null;
  li.focus && li.focus({preventScroll:true});
}

document.addEventListener('pointermove', onDragMove, {passive:false});
document.addEventListener('pointerup', endDrag);
document.addEventListener('pointercancel', endDrag);

