/* ============ drag & drop (Pointer Events, live reorder) ============ */
function getInsertBefore(ul, clientX, clientY){
  const items = $$('.disc-item', ul).filter(li => !li.classList.contains('is-drag'));
  let best = {dist: Infinity, el: null};
  for (const li of items){
    const r = li.getBoundingClientRect();
    if (clientY < r.top || clientY > r.bottom) continue;
    const before = clientY - r.top < r.height / 2;
    const dist = before ? (clientY - r.top) : (r.bottom - clientY);
    if (dist < best.dist) best = {dist, el: before ? li : li.nextElementSibling};
  }
  // если курсор за пределами списка — в начало или конец по вертикали
  if (!best.el){
    const r = ul.getBoundingClientRect();
    return clientY < r.top ? ul.firstElementChild : null;
  }
  return best.el;
}

function makeDraggable(ul){
  let state = null;

  ul.addEventListener('pointerdown', e => {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const li = e.target.closest('.disc-item');
    if (!li || li.parentElement !== ul) return;
    e.preventDefault();
    const r = li.getBoundingClientRect();
    state = {li, offsetX: e.clientX - r.left, startY: r.top, pointerId: e.pointerId};
    li.classList.add('is-drag');
    ul.setPointerCapture && ul.setPointerCapture(e.pointerId);
  });

  ul.addEventListener('pointermove', e => {
    if (!state || e.pointerId !== state.pointerId) return;
    e.preventDefault();
    const li = state.li;
    // позиция элемента без transform
    const cur = li.getBoundingClientRect();
    const tyNow = li._ty || 0;
    const baseTop = cur.top - tyNow;
    const targetTop = (e.clientY - state.startY); // насколько сместить от исходной позиции
    let ty = targetTop - baseTop;
    li._ty = ty;
    li.style.transform = 'translateY(' + ty + 'px)';

    const ref = getInsertBefore(ul, e.clientX, e.clientY);
    if (ref === li) {/* уже на месте */}
    else if (ref && ref !== li && ref !== li.nextElementSibling) ul.insertBefore(li, ref);
    else if (!ref && li.nextElementSibling) ul.insertBefore(li, li.nextElementSibling);
    else if (!ref && li !== ul.lastElementChild) ul.appendChild(li);

    // автопрокрутка диалога у краёв
    const dlgBody = $('.dlg__body');
    const br = dlgBody.getBoundingClientRect();
    const m = 70;
    if (e.clientY < br.top + m) dlgBody.scrollTop -= (br.top + m - e.clientY);
    else if (e.clientY > br.bottom - m) dlgBody.scrollTop += (e.clientY - (br.bottom - m));
  });

  function endDrag(e){
    if (!state) return;
    if (e && e.type === 'pointerup' && e.pointerId !== state.pointerId) return;
    const li = state.li;
    li.style.transform = '';
    li._ty = 0;
    li.classList.remove('is-drag');
    state = null;
    li.focus && li.focus({preventScroll:true});
  }
  ul.addEventListener('pointerup', endDrag);
  ul.addEventListener('pointercancel', endDrag);

  // клавиатура: стрелки вверх/вниз
  ul.addEventListener('keydown', e => {
    const li = e.target.closest('.disc-item');
    if (!li) return;
    if (e.key === 'ArrowUp' && li.previousElementSibling){
      e.preventDefault();
      ul.insertBefore(li, li.previousElementSibling);
      li.focus();
    } else if (e.key === 'ArrowDown' && li.nextElementSibling){
      e.preventDefault();
      ul.insertBefore(li, li.nextElementSibling);
      li.focus();
    }
  });
}

